import './operations.css';
import {createOrganizationUI} from './organization';
import {createAdvancedUI} from './advanced';
type Row=Record<string,any>;
const root=document.querySelector<HTMLDivElement>('#app')!;
const esc=(v:unknown)=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]!));
const money=(v:number)=>new Intl.NumberFormat('en-ZA',{style:'currency',currency:'ZAR'}).format(v/100);
const date=(s:string|null)=>s?new Intl.DateTimeFormat('en-ZA',{timeZone:'Africa/Johannesburg',dateStyle:'medium',timeStyle:'short'}).format(new Date(s)):'—';
const local=(s:string|null)=>s?new Date(Date.parse(s)+7200000).toISOString().slice(0,16):'';
const iso=(s:string)=>s?new Date(s+':00+02:00').toISOString():null;
const status=(s:string)=>`<span class="pill ${esc(s)}">${esc(s.replaceAll('_',' '))}</span>`;
const empty=(text:string)=>`<div class="empty-state"><span aria-hidden="true">◇</span><p>${esc(text)}</p></div>`;
const link=(label:string,target:string,klass='')=>`<a class="${klass}" href="/app#${target}">${esc(label)}</a>`;
const button=(label:string,action:string,cls='secondary',data='')=>`<button class="${cls}" data-action="${action}" ${data}>${esc(label)}</button>`;
let cardDirty=false,renderGeneration=0;
let stockItems:Row[]=[],serviceTemplates:Row[]=[];
let user:Row,company:Row,csrf='',currentJob:Row|null=null,currentCustomer:Row|null=null,users:Row[]=[],teams:Row[]=[];
const permitted=(p:string)=>{const a=user?.permissions||[];return !a.includes('!'+p)&&(a.includes('*')||a.includes(p));};
const manage=()=>user.role!=='technician';
async function api(path:string,method='GET',body?:unknown){const response=await fetch('/api'+path,{signal:AbortSignal.timeout(body instanceof FormData?90000:30000),method,credentials:'same-origin',headers:{...(body instanceof FormData?{}:{'Content-Type':'application/json'}),...(method!=='GET'?{'X-CSRF-Token':csrf}:{})},body:body===undefined?undefined:body instanceof FormData?body:JSON.stringify(body)});if(!response.headers.get('content-type')?.includes('application/json'))throw new Error(response.status===429?'Too many requests. Please wait before retrying.':'Unexpected server response. Check the API service and retry.');const data=await response.json();if(!response.ok){if(response.status===401&&user){user=undefined as any;auth();}throw new Error(data.error||'Request failed');}return data;}
function errorText(e:unknown){return e instanceof Error?e.message:'Unable to complete this action';}
function notice(message:string,kind='success'){const n=document.querySelector<HTMLElement>('#notice');if(n){n.textContent=message;n.className=`notice ${kind}`;n.hidden=false;n.focus();}}
function field(label:string,name:string,value:unknown='',type='text',extra=''){return `<label>${esc(label)}<input name="${name}" aria-label="${esc(label)}" type="${type}" value="${esc(value)}" ${extra}></label>`;}
function area(label:string,name:string,value:unknown='',extra=''){return `<label class="wide">${esc(label)}<textarea name="${name}" aria-label="${esc(label)}" rows="3" ${extra}>${esc(value)}</textarea></label>`;}
function select(label:string,name:string,options:[string,string][],value:unknown='',extra=''){return `<label>${esc(label)}<select name="${name}" aria-label="${esc(label)}" ${extra}>${options.map(([v,t])=>`<option value="${esc(v)}" ${v===value?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;}
const values=(form:HTMLFormElement)=>Object.fromEntries(new FormData(form).entries()) as Record<string,string>;
const advanced=createAdvancedUI({api,esc,money,date,local,iso,field,area,select,button,status,empty,title,modal,values,notice,link,render,user:()=>user,company:()=>company,job:()=>currentJob});
const organization=createOrganizationUI({api,esc,money,date,field,area,select,button,status,empty,title,modal,values,notice,link,render,user:()=>user,company:()=>company,job:()=>currentJob,download:async(path:string,body:unknown,name:string)=>{const r=await fetch('/api'+path,{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify(body)});if(!r.ok)throw new Error((await r.json()).error);const url=URL.createObjectURL(await r.blob()),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}});
function modal(title:string,body:string,onSubmit?:(f:HTMLFormElement)=>Promise<void>){document.querySelector('#modal')?.remove();document.body.insertAdjacentHTML('beforeend',`<dialog id="modal" aria-labelledby="modal-title"><form id="modal-form"><div class="modal-head"><h2 id="modal-title">${esc(title)}</h2><button type="button" class="icon-button" id="modal-close" aria-label="Close dialog">×</button></div><div class="form-error" role="alert" hidden></div><div class="form-grid">${body}</div>${onSubmit?'<div class="form-actions"><button class="primary" type="submit">Save</button></div>':''}</form></dialog>`);const d=document.querySelector<HTMLDialogElement>('#modal')!;document.querySelector('#modal-close')!.addEventListener('click',()=>d.close());d.addEventListener('close',()=>d.remove());d.showModal();if(onSubmit)document.querySelector('#modal-form')!.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as HTMLFormElement;const b=f.querySelector<HTMLButtonElement>('button[type=submit]')!;b.disabled=true;try{await onSubmit(f);d.close();await render();}catch(err){const el=f.querySelector<HTMLElement>('.form-error')!;el.textContent=errorText(err);el.hidden=false;}finally{b.disabled=false;}});return d;}
function logo(){return `<a class="ops-brand" href="/" aria-label="MzansiPlumb home"><img src="/brand/mzansiplumb.png" alt="MzansiPlumb — Manage Today. Grow Tomorrow." width="2171" height="724"/><span>Mzansi<span>Plumb</span></span></a>`;}
function wireLogo(){document.querySelectorAll<HTMLImageElement>('.ops-brand img').forEach(i=>{i.removeAttribute('onerror');const update=()=>{i.hidden=!i.naturalWidth;const fallback=i.nextElementSibling as HTMLElement;fallback.hidden=!!i.naturalWidth;};i.addEventListener('load',update);i.addEventListener('error',update);update();});}
function auth(mode=new URLSearchParams(location.search).get('mode')||'signin'){
 const register=mode==='signup';root.innerHTML=`<div class="auth-layout"><aside class="auth-story">${logo()}<div><span class="overline">BUILT FOR SOUTH AFRICAN PLUMBERS</span><h1>Manage today.<br><em>Grow tomorrow.</em></h1><p>Keep every customer, job and site visit connected in one company workspace.</p><ul><li>Customers and service properties</li><li>Scheduling and digital job cards</li><li>Quotations and work evidence</li></ul></div><small>Development release · Billing disabled</small></aside><main class="auth-main"><div class="auth-card"><a class="back-link" href="/">← Back to website</a><h2>${register?'Create your workspace':'Welcome back'}</h2><p>${register?'Start with your company and owner account.':'Sign in to your company workspace.'}</p><form id="auth-form"><div class="form-error" role="alert" hidden></div>${register?field('Company name','company','','text','required maxlength="160"')+field('Your name','name','','text','required maxlength="160"'):''}${field('Email address','email','','email','required autocomplete="username"')}${field('Password','password','','password',`required minlength="12" maxlength="128" autocomplete="${register?'new-password':'current-password'}"`)}${register?'<small>Use at least 12 characters. Store this password securely; recovery delivery requires the configured company email service.</small>':''}<button class="primary" type="submit">${register?'Create workspace':'Sign in'}</button></form><p><button type="button" id="forgot-password" class="text-button">Forgot password?</button></p><p class="auth-switch">${register?'Already have a workspace?':'New to MzansiPlumb?'} <button id="auth-switch" class="text-button">${register?'Sign in':'Create workspace'}</button></p><p class="quiet">No payment details collected. Use test or non-sensitive information until production deployment has been reviewed.</p></div></main></div>`;wireLogo();document.querySelector('#forgot-password')!.addEventListener('click',()=>void recovery());document.querySelector('#auth-switch')!.addEventListener('click',()=>auth(register?'signin':'signup'));document.querySelector('#auth-form')!.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as HTMLFormElement,b=f.querySelector('button')!;b.disabled=true;try{const result=await api('/auth/'+(register?'register':'login'),'POST',values(f));user=result.user;csrf=result.csrf;history.replaceState(null,'','/app');await boot();}catch(err){const el=f.querySelector<HTMLElement>('.form-error')!;el.textContent=errorText(err);el.hidden=false;}finally{b.disabled=false;}});
}
async function boot(){company=await api('/company');stockItems=await api('/inventory/available');if(manage())serviceTemplates=await api('/templates');if(manage())[users,teams]=await Promise.all([api('/users'),api('/teams')]);shell();await render();}
function shell(){root.innerHTML=`<div class="workspace"><aside class="sidebar">${logo()}<div class="workspace-label"><span class="company-avatar">${esc(company.name.slice(0,1).toUpperCase())}</span><div><strong>${esc(company.name)}</strong><small>Company workspace</small></div></div><nav aria-label="Workspace navigation">${[['dashboard','Overview','◫'],['customers','Customers & properties','♧'],['jobs','Job register','▤'],['schedule','Schedule','▦'],...(manage()?[['quotes','Quotations','▧'],['team','Team & assignments','♙']]:[]),...(manage()?[['followups','Follow-up queue','↻'],['maintenance','Maintenance','◷'],['stock','Stock & materials','▥'],['reports','Revenue & operations','▧'],['templates','Service templates','☷'],['notifications','Automation & inbox','♧'],['audit','Audit history','≡']]:[]),['organization','Branches & service areas','⌂'],['workload','Team workload','◷'],['approvals','Internal approvals','✓'],['pricing','Service price book','R'],['branding','Document branding','◈'],['privacy','Privacy & data','◇'],['subscription','Plan & access','▧'],['company','Company & account','⚙']].filter(([t])=>permitted(({organization:'team.read',workload:'team.read',approvals:'approvals.read',pricing:'quotes.read',branding:'company.manage',privacy:'company.manage',team:'team.read',quotes:'quotes.read',reports:'reports.read',stock:'inventory.read',maintenance:'maintenance.read',templates:'templates.read',notifications:'tasks.read',audit:'audit.read',followups:'tasks.read'} as Record<string,string>)[t]||'jobs.read')).map(([t,l,i])=>`<a href="/app#${t}" data-nav="${t}"><span aria-hidden="true">${i}</span>${l}</a>`).join('')}</nav><div class="sidebar-foot"><span class="pill">Payments disabled</span><a href="/">← Website</a></div></aside><div class="workspace-main"><header class="workspace-top"><button id="sidebar-toggle" class="icon-button" aria-label="Toggle workspace navigation" aria-expanded="false">☰</button><form id="global-search"><label class="sr-only" for="global-q">Search jobs and customers</label><input id="global-q" name="q" placeholder="Search jobs, customers, addresses…" maxlength="160"><button class="text-button">Search</button></form><div class="user-chip"><span>${esc(user.name)}</span><small>${esc(user.role)}</small></div>${button('Sign out','logout','text-button')}</header><main class="workspace-content" id="workspace-content"><div id="notice" role="status" tabindex="-1" hidden></div><div id="view"></div></main><footer class="ops-footer">South Africa · ZAR · Times shown in SAST (UTC+02:00)<span>Development release</span></footer></div></div>`;wireLogo();document.querySelector('#sidebar-toggle')!.addEventListener('click',()=>{const el=document.querySelector('.workspace')!;const on=el.classList.toggle('menu-open');document.querySelector('#sidebar-toggle')!.setAttribute('aria-expanded',String(on));});document.querySelector('#global-search')!.addEventListener('submit',e=>{e.preventDefault();location.hash='search/'+encodeURIComponent(values(e.target as HTMLFormElement).q);});}
function title(eyebrow:string,h:string,description:string,actions=''){return `<div class="view-heading"><div><span class="overline">${esc(eyebrow)}</span><h1>${esc(h)}</h1><p>${esc(description)}</p></div><div class="heading-actions">${actions}</div></div>`;}
function jobTable(jobs:Row[]){return jobs.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Job / customer</th><th>Property / issue</th><th>Status</th><th>Visit · SAST</th><th>Assigned</th></tr></thead><tbody>${jobs.map(j=>`<tr><td>${link(j.reference,'jobs/'+j.id,'record-link')}<small>${esc(j.customer_name)}</small></td><td><strong>${esc(j.property_label)}</strong><small>${esc(j.description.slice(0,85))}</small></td><td>${status(j.status)}${j.deadline&&j.deadline<new Date().toISOString()&&!['completed','cancelled'].includes(j.status)?'<small class="danger-text">Overdue</small>':''}${j.urgency!=='routine'?`<small class="danger-text">${esc(j.urgency)}</small>`:''}</td><td>${date(j.scheduled_start)}</td><td>${j.assignees?esc(j.assignees.map((a:Row)=>a.name).join(', ')||'Unassigned'):'—'}</td></tr>`).join('')}</tbody></table></div>`:empty('No jobs match this view.');}
async function dashboard(){const d=await api('/dashboard');return title('YOUR OPERATIONS','A clear view of your business','Live figures from your company records.',manage()?button('+ Create job','new-job','primary'):'')+`<div class="stats-grid">${[['Total jobs',d.total,'blue'],['In progress',d.in_progress,'amber'],['Overdue',d.overdue,'red'],['Unassigned',d.unassigned,'slate'],...(d.pending_quotes===null?[]:[['Pending quotes',d.pending_quotes,'green']])].map(([l,v,c])=>`<div class="stat ${c}"><span>${l}</span><strong>${v}</strong></div>`).join('')}</div><div class="panel"><div class="panel-heading"><h2>Upcoming visits</h2>${link('View schedule →','schedule')}</div>${jobTable(d.upcoming)}</div><div class="panel"><div class="panel-heading"><h2>Recently completed</h2>${link('All jobs →','jobs')}</div>${jobTable(d.recently_completed)}</div>${await advanced.dashboard()}`;}
async function customerList(q=''){const customers=await api('/customers?q='+encodeURIComponent(q));return title('CUSTOMER RELATIONSHIPS','Customers & properties','Every service address and job history in one place.',manage()?button('+ Add customer','new-customer','primary'):'')+`<form id="customer-search" class="filter-bar">${field('Search customers','q',q,'search')}<button class="secondary">Search</button></form><div class="panel">${customers.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Customer</th><th>Contact details</th><th>Status</th></tr></thead><tbody>${customers.map((c:Row)=>`<tr><td>${link(c.name,'customers/'+c.id,'record-link')}</td><td>${esc(c.email)}<small>${esc(c.phone)}</small></td><td>${status(c.archived?'archived':'active')}</td></tr>`).join('')}</tbody></table></div>`:empty('No customers yet. Add your first customer to get started.')}</div>`;}
async function customerDetail(customerId:string){const c=await api('/customers/'+customerId);if(location.hash==='#customers/'+customerId)currentCustomer=c;return title('CUSTOMER RECORD',c.name,'Contact information, service properties and job history.',manage()?button('Edit customer','edit-customer')+button('+ Add property','new-property','primary'):'')+`<div class="detail-grid"><section class="panel padded"><h2>Contact details</h2><dl><dt>Email</dt><dd>${esc(c.email||'Not recorded')}</dd><dt>Phone</dt><dd>${esc(c.phone||'Not recorded')}</dd><dt>Status</dt><dd>${status(c.archived?'archived':'active')}</dd><dt>Customer notes</dt><dd class="preserve">${esc(c.notes||'No notes')}</dd></dl></section><section class="panel padded"><h2>Service properties</h2>${c.properties.length?c.properties.map((p:Row)=>`<article class="property-record"><div><h3>${esc(p.label)} ${p.archived?status('archived'):''}</h3><p>${esc(p.address)}</p><p class="quiet preserve">${esc(p.notes)}</p>${link('View property job history →','property/'+p.id)}</div>${manage()?button('Edit','edit-property','text-button',`data-id="${p.id}"`):''}</article>`).join(''):empty('No properties recorded.')}</section></div><section class="panel"><div class="panel-heading"><h2>Customer job history</h2>${manage()?button('+ Create job','new-job','text-button'):''}</div>${jobTable(c.jobs)}</section>${c.history.length?`<section class="panel padded"><h2>Record history</h2>${historyList(c.history)}</section>`:''}`;}
function historyList(rows:Row[]){return `<ol class="activity-list">${rows.map(h=>`<li><div><strong>${esc(h.action.replaceAll('.',' · '))}</strong><p>${esc(h.detail)}</p><small>${esc(h.actor_name||(h.source==='system'?'Automation':h.source==='customer'?'Customer link action':'User unavailable'))} · ${date(h.created_at)}</small></div></li>`).join('')}</ol>`;}
async function jobRegister(q='',statusFilter='',urgency=''){const params=new URLSearchParams({q,status:statusFilter,urgency});const jobs=await api('/jobs?'+params);return title('DAILY OPERATIONS','Job register','Track every call-out from first report to completed work.',manage()?button('+ Create job','new-job','primary'):'')+`<form id="job-filters" class="filter-bar">${field('Search reference, customer or issue','q',q,'search')}${select('Status','status',[['','All statuses'],...['new','scheduled','in_progress','completed','cancelled'].map(s=>[s,s.replaceAll('_',' ')] as [string,string])],statusFilter)}${select('Urgency','urgency',[['','All urgency'],['routine','Routine'],['urgent','Urgent'],['emergency','Emergency']],urgency)}<button class="secondary">Apply filters</button></form><div class="panel">${jobTable(jobs)}</div>`;}
async function schedule(){const jobs=await api('/jobs');const open=jobs.filter((j:Row)=>!['completed','cancelled'].includes(j.status));const dated=open.filter((j:Row)=>j.scheduled_start).sort((a:Row,b:Row)=>a.scheduled_start.localeCompare(b.scheduled_start));const groups=new Map<string,Row[]>();for(const j of dated){const d=local(j.scheduled_start).slice(0,10);groups.set(d,[...(groups.get(d)||[]),j]);}return title('DISPATCH & SITE VISITS','Schedule','Appointments grouped by South African local date. Open a job to reschedule.',manage()?button('+ Create job','new-job','primary'):'')+`<div class="schedule-groups">${groups.size?[...groups].map(([day,rows])=>`<section class="panel"><div class="panel-heading"><h2>${esc(new Intl.DateTimeFormat('en-ZA',{dateStyle:'full',timeZone:'Africa/Johannesburg'}).format(new Date(day+'T12:00:00+02:00')))}</h2></div>${rows.map(j=>`<article class="schedule-item"><time>${local(j.scheduled_start).slice(11)}<small>to ${local(j.scheduled_end).slice(11)}</small></time><div>${link(j.reference+' · '+j.customer_name,'jobs/'+j.id,'record-link')}<p>${esc(j.property_address)}</p><small>${esc(j.assignees.map((a:Row)=>a.name).join(', ')||'Unassigned')}</small></div>${status(j.status)}</article>`).join('')}</section>`).join(''):empty('No scheduled visits.')}</div><section class="panel"><div class="panel-heading"><h2>Unscheduled jobs</h2></div>${jobTable(open.filter((j:Row)=>!j.scheduled_start))}</section>`;}
async function jobDetail(jobId:string){const j=await api('/jobs/'+jobId);stockItems=await api('/inventory/available');if(location.hash==='#jobs/'+jobId)currentJob=j;const closed=['completed','cancelled'].includes(j.status),c=j.card||{};return title(j.reference,j.description,'Job details, site records, evidence and quotations.',`${!closed&&manage()?button('Edit job','edit-job')+button('Assign / schedule','schedule-job','primary'):''}${j.status==='completed'?`<a class="primary" href="/api/jobs/${j.id}/report">Download service report</a>`:''}`)+`<div class="job-summary"><span>${status(j.status)}</span><span>${status(j.urgency)}</span><span>Visit: ${date(j.scheduled_start)}</span><span>Deadline: ${date(j.deadline)}</span></div><div class="detail-grid"><section class="panel padded"><h2>Customer & service property</h2><p>${link(j.customer.name,'customers/'+j.customer.id,'record-link')}</p><p>${esc(j.customer.phone)} · ${esc(j.customer.email)}</p><h3>${esc(j.property.label)}</h3><p class="preserve">${esc(j.property.address)}</p><p class="quiet preserve">${esc(j.property.notes)}</p></section><section class="panel padded"><h2>Assignment & job notes</h2><p><strong>Technicians:</strong> ${esc(j.assignees.map((a:Row)=>a.name).join(', ')||'Unassigned')}</p><p><strong>Category:</strong> ${esc(j.category)}</p><p><strong>Visit end:</strong> ${date(j.scheduled_end)}</p><p class="preserve"><strong>Internal notes:</strong> ${esc(j.internal_notes||'None')}</p>${j.cancellation_reason?`<p>Cancellation: ${esc(j.cancellation_reason)}</p>`:''}</section></div>
<section class="panel padded"><div class="panel-heading inline"><div><span class="overline">ON-SITE WORK RECORD</span><h2>Digital job card</h2></div><span class="quiet">${j.card?'Last saved '+date(j.card.updated_at):'Not yet recorded'}</span></div><form id="job-card" class="form-grid"><div class="form-error wide" role="alert" hidden></div>${field('Actual arrival · SAST','arrival',local(c.arrival),'datetime-local',closed?'disabled':'')}${field('Actual completion · SAST','completion',local(c.completion),'datetime-local',closed?'disabled':'')}${area('Findings (or explain why not applicable)','findings',c.findings,closed?'disabled':'')}${area('Work performed (or explain why not applicable)','work',c.work,closed?'disabled':'')}${advanced.checklist(j,closed)}${field('Labour time · minutes','labour_minutes',c.labour_minutes||0,'number',`min="0" step="1" ${closed?'disabled':''}`)}${field('If no labour, explain why','labour_not_applicable',c.labour_not_applicable,'text',closed?'disabled':'')}<div class="wide"><h3>Materials used</h3><div id="material-rows">${(c.materials||[]).map((m:Row)=>materialRow(m,closed)).join('')}</div>${!closed?'<button type="button" class="text-button" id="add-material">+ Add material</button>':''}</div>${field('If no materials, explain why','materials_not_applicable',c.materials_not_applicable,'text',closed?'disabled':'')}${field('If photos are not applicable, explain why','evidence_not_applicable',c.evidence_not_applicable,'text',closed?'disabled':'')}${area('Additional work required','additional_work',c.additional_work,closed?'disabled':'')}${area('Technician notes (internal)','notes',c.notes,closed?'disabled':'')}<div class="wide form-actions">${closed?'<p class="quiet">Closed job cards are read-only. Customer signature: not captured.</p>':'<p class="quiet">Save progress before leaving this page. Completion validates work, times, materials and evidence.</p><button class="primary" type="submit">Save job card</button>'}</div></form></section>
<section class="panel padded"><div class="panel-heading inline"><h2>Photos & attachments</h2>${closed?'':button('+ Upload evidence','upload')}</div><p class="quiet">Private to authorized workspace members. Images are normalized and location metadata removed. Maximum 8 MB per upload.</p><div class="file-grid">${j.files.length?j.files.map((f:Row)=>`<a href="/api/files/${f.id}" target="_blank" rel="noopener" class="file-card">${f.mime.startsWith('image/')?`<img src="/api/files/${f.id}" alt="${esc(f.kind)} evidence: ${esc(f.name)}" loading="lazy">`:'<span class="pdf-icon">PDF</span>'}<strong>${esc(f.kind)}</strong><small>${esc(f.name)}</small></a>`).join(''):empty('No evidence or attachments uploaded.')}</div></section>
${manage()?`<section class="panel padded"><div class="panel-heading inline"><h2>Quotations</h2>${closed?'':button('+ Prepare quotation','new-quote')}</div><p class="quiet">ZAR · VAT per company settings. Approval records a real link-holder decision; no email or SMS is sent.</p>${j.quotes.map((q:Row)=>`<article class="quote-record"><div><strong>Quotation · Revision ${q.revision}</strong> ${status(q.status==='issued'&&q.expires_at<new Date().toISOString()?'expired':q.status)}<p>${money(q.data.total_cents)} · Expires ${date(q.expires_at)}</p>${q.decision_at?`<p>${esc(q.status)} by ${esc(q.decision_by)} · ${date(q.decision_at)}<br><small>Via private link; identity self-declared. ${esc(q.decision_note)}</small></p>`:''}</div><div class="action-row">${!closed?(q.status==='draft'?button('Edit','edit-quote','secondary',`data-id="${q.id}"`)+button('Issue / get link','issue-quote','primary',`data-id="${q.id}"`):button('Create revision','revise-quote','secondary',`data-id="${q.id}"`)):''}${button('Revision history','quote-history','text-button',`data-id="${q.id}"`)}</div></article>`).join('')||empty('No quotations prepared.')}</section>`:''}
<div class="action-row"><a class="secondary" href="/api/jobs/${j.id}/card.pdf">Download job card</a>${permitted('approvals.write')?button('Request internal approval','org-request'):''}${link('Internal decisions','approvals','secondary')}</div>${await advanced.jobSections(j)}<section class="panel padded"><h2>Activity history</h2>${historyList(j.history)}</section>${!closed?`<div class="completion-bar"><p>Complete only after saving and reviewing the job card.<br><small>Customer signature is not captured in this phase.</small></p><div class="action-row">${manage()?button('Cancel job','cancel-job','danger'):''}${button('Mark job complete','complete-job','primary')}</div></div>`:''}`;}
function materialRow(m:Row={},disabled=false){const options:[string,string][]=[['','Free-form material (not stock-linked)'],...stockItems.map(i=>[i.id,i.name+' · '+(i.quantity_milli/1000)+' '+i.unit] as [string,string])];if(m.stock_item_id&&!stockItems.some(i=>i.id===m.stock_item_id))options.push([m.stock_item_id,m.name+' (previous stock item)']);return `<div class="material-row">${select('Stock item (optional)','material_stock',options,m.stock_item_id||'',disabled?'disabled':'')}${field('Material','material_name',m.name||'','text',`required maxlength="160" ${disabled?'disabled':m.stock_item_id?'readonly':''}`)}${field('Quantity','material_quantity',m.quantity||1,'number',`required min="0.001" step="0.001" ${disabled?'disabled':''}`)}${field('Unit','material_unit',m.unit||'each','text',`required maxlength="30" ${disabled?'disabled':m.stock_item_id?'readonly':''}`)}${disabled?'':'<button type="button" class="icon-button remove-row" aria-label="Remove material">×</button>'}</div>`;}
async function quoteList(){const rows=await api('/quotations');return title('CUSTOMER DECISIONS','Quotations','Drafts, issued revisions and actual customer link decisions.')+`<section class="panel">${rows.length?`<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Job</th><th>Revision</th><th>Status</th><th>Total · ZAR</th><th>Expiry</th></tr></thead><tbody>${rows.map((q:Row)=>`<tr><td>${link(q.reference+' · '+q.customer_name,'jobs/'+q.job_id,'record-link')}</td><td>${q.revision}</td><td>${status(q.status==='issued'&&q.expires_at<new Date().toISOString()?'expired':q.status)}</td><td>${money(q.data.total_cents)}</td><td>${date(q.expires_at)}</td></tr>`).join('')}</tbody></table></div>`:empty('Prepare a quotation from a job record.')}</section>`;}
async function teamView(){[users,teams]=await Promise.all([api('/users'),api('/teams')]);return title('PEOPLE & PERMISSIONS','Team & assignments','Technicians can access only jobs assigned to them.',(permitted('company.manage')?button('+ Add member','new-member','primary'):'')+button('+ Create team','new-team'))+`<div class="panel"><div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Member</th><th>Role</th><th>Status</th><th>Access</th></tr></thead><tbody>${users.map(u=>`<tr><td><strong>${esc(u.name)}</strong><small>${esc(u.email)}</small></td><td>${esc(u.role)}</td><td>${status(u.active?'active':'disabled')}</td><td>${permitted('company.manage')&&u.role!=='owner'?button('Manage','edit-member','text-button',`data-id="${u.id}"`):'—'}</td></tr>`).join('')}</tbody></table></div></div><section class="panel padded"><h2>Teams</h2><p class="quiet">Assigning a team snapshots its members onto the job. Subsequent permission changes do not silently change assignments.</p>${teams.length?teams.map(t=>`<article class="property-record"><div><h3>${esc(t.name)}</h3><p>${esc(t.user_ids.map((id:string)=>users.find(u=>u.id===id)?.name||'Unavailable member').join(', '))}</p></div></article>`).join(''):empty('No teams created.')}</section>`;}
async function companyView(){company=await api('/company');return title('WORKSPACE SETTINGS','Company & account','Company details appear on downloadable service reports.')+`<section class="panel padded"><h2>Company details & VAT</h2><form id="company-form" class="form-grid"><div class="form-error wide" role="alert" hidden></div>${field('Company name','name',company.name,'text','required')}${field('Company email','email',company.email,'email')}${field('Phone','phone',company.phone)}${field('VAT registration number','vat_number',company.vat_number)}${area('Company address','address',company.address)}${select('VAT status','vat_registered',[['false','Not VAT registered'],['true','VAT registered']],String(!!company.vat_registered))}${field('VAT rate · percent','vat_percent',company.vat_bps/100,'number','min="0" max="100" step="0.01" required')}<p class="quiet wide">New quotations use these settings. Issued revisions preserve their financial snapshot. No payments or billing are enabled.</p>${permitted('company.manage')?'<div class="wide"><button class="primary">Save company settings</button></div>':'<p class="wide quiet">Only the owner can change company details.</p>'}</form></section><section class="panel padded"><h2>Password & sessions</h2><p>Changing your password revokes all your other sessions.</p>${button('Change password','password')}<p class="quiet">Email recovery, email verification and MFA are not configured. Keep owner credentials secure.</p></section>`;}
async function render(){if(!user)return;const generation=++renderGeneration;cardDirty=false;const route=decodeURIComponent(location.hash.slice(1)||'dashboard'),[tab,recordId]=route.split('/');const view=document.querySelector('#view')!;view.innerHTML='<p class="loading" role="status">Loading workspace…</p>';document.querySelectorAll('[data-nav]').forEach(n=>n.classList.toggle('active',(n as HTMLElement).dataset.nav===tab));document.querySelector('.workspace')?.classList.remove('menu-open');document.querySelector('#sidebar-toggle')?.setAttribute('aria-expanded','false');try{let html=await organization.renderTab(tab)||'';if(html){/* Organization view resolved above. */}else if(tab==='dashboard')html=await dashboard();else if(tab==='customers')html=recordId?await customerDetail(recordId):await customerList();else if(tab==='jobs')html=recordId?await jobDetail(recordId):await jobRegister();else if(tab==='schedule')html=await schedule();else if(tab==='quotes'&&manage())html=await quoteList();else if(tab==='team'&&manage())html=await teamView();else if(tab==='company')html=await companyView()+`<section class="panel padded"><h2>Email security</h2><p>${user.email_verified?'Email verified':'Verify your email before public production use.'}</p>${!user.email_verified?button('Request verification email','verify-email'):''}${button('Delivery status','auth-deliveries')}</section>`;else if(['followups','maintenance','stock','reports','templates','notifications','audit'].includes(tab)&&manage())html=await advanced.renderTab(tab,recordId)||'';else if(tab==='search'){html=title('WORKSPACE SEARCH','Search results',`Results for “${recordId||''}”`)+await jobRegister(recordId||'')+await customerList(recordId||'');}else if(tab==='property'){const jobs=await api('/jobs?property_id='+encodeURIComponent(recordId));html=title('PROPERTY RECORD','Property job history','All accessible jobs for this service address.')+`<section class="panel">${jobTable(jobs)}</section>`;}else html=empty('Page not found. Choose a page from workspace navigation.');if(generation!==renderGeneration)return;view.innerHTML=html;applyPermissions();wireForms();advanced.wireForms();}catch(e){if(generation!==renderGeneration)return;view.innerHTML=`<div class="form-error" role="alert">${esc(errorText(e))}</div>`;}}
function wireForms(){const cardForm=document.querySelector('#job-card');for(const event of ['input','change'])cardForm?.addEventListener(event,()=>{cardDirty=true;});document.querySelector('#customer-search')?.addEventListener('submit',async e=>{e.preventDefault();document.querySelector('#view')!.innerHTML=await customerList(values(e.target as HTMLFormElement).q);wireForms();});document.querySelector('#job-filters')?.addEventListener('submit',async e=>{e.preventDefault();const b=values(e.target as HTMLFormElement);document.querySelector('#view')!.innerHTML=await jobRegister(b.q,b.status,b.urgency);wireForms();});document.querySelector('#add-material')?.addEventListener('click',()=>document.querySelector('#material-rows')!.insertAdjacentHTML('beforeend',materialRow()));document.querySelector('#job-card')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as HTMLFormElement;await saveInline(f,async()=>{const b=values(f);const materials=[...f.querySelectorAll<HTMLElement>('.material-row')].map(r=>({name:(r.querySelector('[name=material_name]') as HTMLInputElement).value,quantity:Number((r.querySelector('[name=material_quantity]') as HTMLInputElement).value),unit:(r.querySelector('[name=material_unit]') as HTMLInputElement).value,stock_item_id:(r.querySelector('[name=material_stock]') as HTMLSelectElement).value||null}));await api(`/jobs/${currentJob!.id}/card`,'PUT',{checks:[...f.querySelectorAll<HTMLElement>('.service-check')].map(r=>({id:r.dataset.checkId,done:r.querySelector<HTMLInputElement>('[name=check_done]')!.checked,not_applicable:r.querySelector<HTMLInputElement>('[name=check_na]')!.value})),arrival:iso(b.arrival),completion:iso(b.completion),work:b.work,findings:b.findings,labour_minutes:Number(b.labour_minutes),labour_not_applicable:b.labour_not_applicable,materials,materials_not_applicable:b.materials_not_applicable,evidence_not_applicable:b.evidence_not_applicable,additional_work:b.additional_work,notes:b.notes,version:currentJob!.card?.version||0});await render();notice('Job card saved.');});});const companyForm=document.querySelector<HTMLFormElement>('#company-form');if(companyForm){if(user.role!=='owner')companyForm.querySelectorAll('input,select,textarea').forEach(el=>(el as HTMLInputElement).disabled=true);companyForm.addEventListener('submit',async e=>{e.preventDefault();await saveInline(companyForm,async()=>{const b=values(companyForm);await api('/company','PUT',{name:b.name,address:b.address,phone:b.phone,email:b.email,vat_registered:b.vat_registered==='true',vat_number:b.vat_number,vat_bps:Math.round(Number(b.vat_percent)*100)});company=await api('/company');notice('Company settings saved.');});});}}
async function saveInline(form:HTMLFormElement,fn:()=>Promise<void>){const err=form.querySelector<HTMLElement>('.form-error')!,submit=form.querySelector<HTMLButtonElement>('button[type=submit],button.primary');err.hidden=true;if(submit)submit.disabled=true;try{await fn();}catch(e){err.textContent=errorText(e);err.hidden=false;}finally{if(submit)submit.disabled=false;}}
async function customerModal(edit=false){const c=edit?currentCustomer!:{};modal(edit?'Edit customer':'Add customer',field('Customer / business name','name',c.name,'text','required maxlength="160"')+field('Email','email',c.email,'email')+field('Phone','phone',c.phone,'tel','maxlength="40"')+select('Record status','archived',[['false','Active'],['true','Archived']],String(!!c.archived))+area('Customer notes','notes',c.notes),async f=>{const b=values(f);await api(edit?'/customers/'+c.id:'/customers',edit?'PUT':'POST',{...b,archived:b.archived==='true',...(edit?{version:c.version}:{})});});}
async function propertyModal(propertyId?:string){const c=currentCustomer!,p=c.properties.find((p:Row)=>p.id===propertyId)||{};modal(propertyId?'Edit property':'Add property',field('Property name / label','label',p.label,'text','required maxlength="160"')+select('Record status','archived',[['false','Active'],['true','Archived']],String(!!p.archived))+area('Service address','address',p.address,'required maxlength="1000"')+area('Access instructions / property notes','notes',p.notes),async f=>{const b=values(f);await api(propertyId?'/properties/'+p.id:'/properties',propertyId?'PUT':'POST',{...b,customer_id:c.id,archived:b.archived==='true',...(propertyId?{version:p.version}:{})});});}
async function jobModal(edit=false){const j=edit?currentJob!:{};const customers=(await api('/customers')).filter((c:Row)=>!c.archived||c.id===j.customer_id);if(!customers.length){notice('Add a customer and service property before creating a job.','error');location.hash='customers';return;}const selected=j.customer_id||(customers.some((c:Row)=>c.id===currentCustomer?.id)?currentCustomer!.id:customers[0].id);const customer=await api('/customers/'+selected);serviceTemplates=(await api('/templates')).filter((t:Row)=>!t.archived);const areas=await api('/service-areas');const body=(!edit?await organization.branchFields()+select('Service area (optional)','service_area_id',[['','No service area'],...areas.filter((a:Row)=>a.active&&a.branch_id===user.branch_ids[0]).map((a:Row)=>[a.id,a.name] as [string,string])]):'')+select('Customer','customer_id',customers.map((c:Row)=>[c.id,c.name]),selected,edit?'disabled':'')+select('Service property','property_id',customer.properties.filter((p:Row)=>!p.archived||p.id===j.property_id).length?customer.properties.filter((p:Row)=>!p.archived||p.id===j.property_id).map((p:Row)=>[p.id,p.label+' · '+p.address]):[['','Add a service property to this customer first']],j.property_id,edit?'disabled':'required')+(!edit?select('Service template (optional)','template_id',[['','No template'],...serviceTemplates.map(t=>[t.id,t.name] as [string,string])]):'')+area('Plumbing issue / description','description',j.description,'required maxlength="10000"')+field('Category','category',j.category||'General plumbing','text','required maxlength="100"')+select('Urgency','urgency',[['routine','Routine'],['urgent','Urgent'],['emergency','Emergency']],j.urgency||'routine')+field('Deadline · SAST (optional)','deadline',local(j.deadline),'datetime-local')+area('Internal notes','internal_notes',j.internal_notes);const d=modal(edit?'Edit job':'Create job',body,async f=>{const b=values(f);const data={...b,...(!edit?{template_id:b.template_id||null,service_area_id:b.service_area_id||null}:{}),customer_id:edit?j.customer_id:b.customer_id,property_id:edit?j.property_id:b.property_id,deadline:iso(b.deadline),...(edit?{version:j.version}:{})};const result=await api(edit?'/jobs/'+j.id:'/jobs',edit?'PUT':'POST',data);if(!edit)location.hash='jobs/'+result.id;});d.querySelector('[name=branch_id]')?.addEventListener('change',(e:Event)=>{const s=d.querySelector<HTMLSelectElement>('[name=service_area_id]')!;s.innerHTML='<option value="">No service area</option>'+areas.filter((a:Row)=>a.active&&a.branch_id===(e.target as HTMLSelectElement).value).map((a:Row)=>`<option value="${a.id}">${esc(a.name)}</option>`).join('');});d.querySelector('[name=template_id]')?.addEventListener('change',(e:Event)=>{const t=serviceTemplates.find(t=>t.id===(e.target as HTMLSelectElement).value);if(t){(d.querySelector('[name=description]') as HTMLTextAreaElement).value=t.description;(d.querySelector('[name=category]') as HTMLInputElement).value=t.category;}});d.querySelector('[name=customer_id]')!.addEventListener('change',async e=>{try{const c=await api('/customers/'+(e.target as HTMLSelectElement).value);const s=d.querySelector<HTMLSelectElement>('[name=property_id]')!;s.innerHTML=c.properties.filter((p:Row)=>!p.archived).map((p:Row)=>`<option value="${p.id}">${esc(p.label+' · '+p.address)}</option>`).join('');if(!s.options.length)s.innerHTML='<option value="">Add a property to this customer first</option>';}catch(e){notice(errorText(e),'error');}});}
async function scheduleModal(){const j=currentJob!;[users,teams]=await Promise.all([api('/users'),api('/teams')]);modal('Assign technicians & schedule',`<p class="quiet wide">Times are SAST. Overlapping appointments for an assigned technician are rejected. Team members are added to the selected individuals.</p><fieldset class="wide"><legend>Individual technicians</legend>${users.filter(u=>u.active&&['technician','owner'].includes(u.role)).map(u=>`<label class="check"><input type="checkbox" name="assignee" value="${u.id}" ${j.assignees.some((a:Row)=>a.id===u.id)?'checked':''}>${esc(u.name)}</label>`).join('')}</fieldset>`+select('Team (optional)','team_id',[['','No team'],...teams.map(t=>[t.id,t.name] as [string,string])],j.team_id||'')+field('Visit starts · SAST','scheduled_start',local(j.scheduled_start),'datetime-local')+field('Visit ends · SAST','scheduled_end',local(j.scheduled_end),'datetime-local'),async f=>{const b=values(f);await api(`/jobs/${j.id}/schedule`,'PUT',{user_ids:new FormData(f).getAll('assignee'),team_id:b.team_id||null,scheduled_start:iso(b.scheduled_start),scheduled_end:iso(b.scheduled_end),version:j.version});});}
function quoteRow(i:Row={}){return `<div class="quote-line">${field('Description','item_description',i.description,'text','required maxlength="500"')}${select('Type','item_kind',[['labour','Labour'],['material','Material'],['other','Other']],i.kind||'labour')}${field('Qty','item_quantity',i.quantity||1,'number','required min="0.001" max="10000" step="0.001"')}${field('Unit price · ZAR','item_price',(i.unit_cents||0)/100,'number','required min="0" max="1000000" step="0.01"')}<button type="button" class="icon-button remove-row" aria-label="Remove quotation item">×</button></div>`;}
async function quoteModal(quoteId?:string){const pricebook=(await api('/pricebook')).filter((p:Row)=>p.active);const j=currentJob!,q=j.quotes.find((q:Row)=>q.id===quoteId),data=q?.data||{};const d=modal(quoteId?'Edit quotation draft':'Prepare quotation',`<div class="wide"><p class="quiet">VAT: ${company.vat_registered?company.vat_bps/100+'% (registered)':'not VAT registered'}. Totals are recalculated and validated on the server.</p>${select('Add from service price book','pricebook',[['','Select a configured price'],...pricebook.map((p:Row)=>[p.id,p.code+' · '+p.description+' · '+money(p.unit_cents)] as [string,string])])}<div id="quote-lines">${(data.items||[{}]).map((i:Row)=>quoteRow(i)).join('')}</div><button id="add-quote-line" type="button" class="text-button">+ Add line item</button></div>`+field('Discount · ZAR','discount',data.discount_cents?data.discount_cents/100:0,'number','required min="0" step="0.01"')+field('Expires · SAST','expires_at',local(q?.expires_at||new Date(Date.now()+7*86400000).toISOString()),'datetime-local','required')+area('Customer-facing quotation notes','notes',data.notes),async f=>{const b=values(f);const items=[...f.querySelectorAll('.quote-line')].map(r=>({description:(r.querySelector('[name=item_description]') as HTMLInputElement).value,kind:(r.querySelector('[name=item_kind]') as HTMLSelectElement).value,quantity:Number((r.querySelector('[name=item_quantity]') as HTMLInputElement).value),unit_cents:Math.round(Number((r.querySelector('[name=item_price]') as HTMLInputElement).value)*100)}));await api(quoteId?'/quotes/'+quoteId:`/jobs/${j.id}/quotes`,quoteId?'PUT':'POST',{items,discount_cents:Math.round(Number(b.discount)*100),expires_at:iso(b.expires_at),notes:b.notes,...(q?{version:q.version}:{})});});d.querySelector('[name=pricebook]')?.addEventListener('change',(e:Event)=>{const p=pricebook.find((p:Row)=>p.id===(e.target as HTMLSelectElement).value);if(p)d.querySelector('#quote-lines')!.insertAdjacentHTML('beforeend',quoteRow({...p,quantity:1}));});d.querySelector('#add-quote-line')!.addEventListener('click',()=>d.querySelector('#quote-lines')!.insertAdjacentHTML('beforeend',quoteRow()));}
async function uploadModal(){const j=currentJob!;modal('Upload private evidence',select('Evidence type','kind',[['before','Before photo'],['after','After photo'],['attachment','General attachment']])+field('Image or PDF attachment (8 MB maximum)','file','','file','required accept="image/jpeg,image/png,image/webp,application/pdf"'),async f=>{await api(`/jobs/${j.id}/files`,'POST',new FormData(f));});}
async function actions(action:string,el:HTMLElement){if(action==='verify-email'){const r=await api('/auth/verification-request','POST',{});notice(r.message+(r.email_configured?'':' Email service is not configured.'),'success');return;}if(action==='auth-deliveries'){const r=await api('/auth/email-status');modal('Account email delivery',`<div class="wide"><p>Email ${r.verified?'verified':'not verified'}. Delivery service ${r.email_configured?'configured':'not configured'}.</p>${r.deliveries.map((d:Row)=>`<p>${esc(d.kind)} · ${esc(d.state)} · ${date(d.created_at)} · ${esc(d.error_code||'')}</p>`).join('')}<p class="quiet">Accepted means the provider accepted the request; delivery requires a signed callback.</p></div>`);return;}if(await organization.handleAction(action,el))return;if(await advanced.handleAction(action,el))return;if(action==='logout'){await api('/auth/logout','POST',{});location.href='/app';}else if(action==='new-customer')await customerModal();else if(action==='edit-customer')await customerModal(true);else if(action==='new-property')await propertyModal();else if(action==='edit-property')await propertyModal(el.dataset.id);else if(action==='new-job')await jobModal();else if(action==='edit-job')await jobModal(true);else if(action==='schedule-job')await scheduleModal();else if(action==='upload')await uploadModal();else if(action==='new-quote')await quoteModal();else if(action==='edit-quote')await quoteModal(el.dataset.id);else if(action==='cancel-job'){const j=currentJob!;modal('Cancel job',area('Reason for cancellation','reason','','required maxlength="2000"'),async f=>{await api(`/jobs/${j.id}/cancel`,'POST',{reason:values(f).reason,version:j.version});});}else if(action==='complete-job'){const j=currentJob!;modal('Complete job',`<p class="wide">Confirm that the saved job card and evidence are correct. The job will become read-only. No customer signature is captured and no message will be sent.</p>`,async()=>{await api(`/jobs/${j.id}/complete`,'POST',{version:j.version});});}else if(action==='issue-quote'){const q=currentJob!.quotes.find((q:Row)=>q.id===el.dataset.id);const r=await api(`/quotes/${q.id}/issue`,'POST',{version:q.version});await render();modal('Quotation issued — share manually',`<p class="wide">No email or SMS was sent. Copy this private link and send it to the intended customer. Anyone holding the link can record a decision; identity is self-declared.</p><label class="wide">Customer approval link<input readonly value="${esc(r.approval_url)}" id="approval-link"></label><button type="button" id="copy-link" class="secondary">Copy link</button><p id="copy-status" class="quiet wide" role="status"></p>`);document.querySelector('#copy-link')!.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(r.approval_url);document.querySelector('#copy-status')!.textContent='Link copied.';}catch{document.querySelector<HTMLInputElement>('#approval-link')!.select();document.querySelector('#copy-status')!.textContent='Select and copy the link manually.';}});}else if(action==='revise-quote'){const q=currentJob!.quotes.find((q:Row)=>q.id===el.dataset.id);modal('Create quotation revision',`<p class="wide">This will preserve the issued revision and any decision, revoke the previous link, and return the quotation to draft for editing. It does not carry approval forward.</p>`,async()=>{await api(`/quotes/${q.id}/revise`,'POST',{version:q.version});});}else if(action==='quote-history'){const rows=await api(`/quotes/${el.dataset.id}/revisions`);modal('Issued quotation revisions',`<div class="wide">${rows.length?rows.map((r:Row)=>`<article class="quote-record"><div><h3>Revision ${r.revision} · ${money(r.snapshot.total_cents)}</h3><p>Issued ${date(r.created_at)}</p><p>VAT ${r.snapshot.vat_bps/100}% · Discount ${money(r.snapshot.discount_cents)}</p>${r.snapshot.items.map((i:Row)=>`<p>${esc(i.description)} · ${i.quantity} × ${money(i.unit_cents)}</p>`).join('')}<p>${esc(r.snapshot.decision?`${r.snapshot.decision.status} by ${r.snapshot.decision.name} on ${date(r.snapshot.decision.at)}`:'No decision recorded on this revision.')}</p></div></article>`).join(''):empty('No issued revisions.')}</div>`);}else if(action==='new-member'){const branches=await organization.branchFields(user.company_id,true);modal('Add workspace member',field('Full name','name','','text','required')+field('Email','email','','email','required')+select('Role','role',organization.roleOptions)+branches+field('Initial password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+'<p class="quiet wide">No invitation email is sent. Share credentials securely; the member can change their password in Company & account.</p>',async f=>{const b=values(f);delete b.branch;await api('/users','POST',{...b,branch_ids:new FormData(f).getAll('branch')});});}else if(action==='edit-member'){const u=users.find(u=>u.id===el.dataset.id)!;const branches=await organization.branchFields(u.branch_ids.join(','),true);modal('Manage '+u.name,select('Access','active',[['true','Active'],['false','Disabled']],String(!!u.active))+select('Role','role',organization.roleOptions,u.role)+branches,async f=>{const b=values(f);await api('/users/'+u.id,'PATCH',{active:b.active==='true',role:b.role,branch_ids:new FormData(f).getAll('branch')});});}else if(action==='new-team'){modal('Create technician team',await organization.branchFields()+field('Team name','name','','text','required')+`<fieldset class="wide"><legend>Members</legend>${users.filter(u=>u.active&&['technician','owner'].includes(u.role)).map(u=>`<label class="check"><input type="checkbox" name="member" value="${u.id}">${esc(u.name)}</label>`).join('')}</fieldset>`,async f=>{await api('/teams','POST',{name:values(f).name,branch_id:values(f).branch_id,user_ids:new FormData(f).getAll('member')});});}else if(action==='password'){modal('Change password',field('Current password','current_password','','password','required autocomplete="current-password"')+field('New password','new_password','','password','required minlength="12" maxlength="128" autocomplete="new-password"'),async f=>{const r=await api('/auth/password','POST',values(f));csrf=r.csrf;});}}
document.addEventListener('click',async e=>{const target=e.target as HTMLElement;if(target.closest('.remove-row')){target.closest('.material-row,.quote-line')?.remove();return;}const el=target.closest<HTMLElement>('[data-action]');if(!el)return;el.setAttribute('disabled','');try{await actions(el.dataset.action!,el);}catch(e){notice(errorText(e),'error');}finally{el.removeAttribute('disabled');}});
document.addEventListener('change',e=>{const target=e.target as HTMLSelectElement;if(target.name!=='material_stock')return;const row=target.closest('.material-row')!,item=stockItems.find(i=>i.id===target.value),name=row.querySelector<HTMLInputElement>('[name=material_name]')!,unit=row.querySelector<HTMLInputElement>('[name=material_unit]')!;name.readOnly=!!item;unit.readOnly=!!item;if(item){name.value=item.name;unit.value=item.unit;}});
window.addEventListener('beforeunload',e=>{if(cardDirty){e.preventDefault();e.returnValue=true;}});
document.addEventListener('click',e=>{const a=(e.target as HTMLElement).closest<HTMLAnchorElement>('a[href^="/app#"]');if(a&&cardDirty){if(!confirm('Leave without saving your job card changes?')){e.preventDefault();e.stopPropagation();}else cardDirty=false;}},true);
window.addEventListener('hashchange',()=>{if(/^#(reset-password|verify-email)\//.test(location.hash))void recovery();else void render();});
async function approval(){const token=location.pathname.split('/')[2];try{const q=await api('/approval/'+encodeURIComponent(token));root.innerHTML=`<main class="approval-page">${logo()}<section class="panel padded"><span class="overline">CUSTOMER QUOTATION</span><h1>${esc(q.data.company?.branding?.trading_name||q.company.name)}</h1>${q.data.company?.branding?.logo_base64?`<img src="data:image/png;base64,${esc(q.data.company.branding.logo_base64)}" alt="Company logo" style="max-width:240px;max-height:100px">`:''}<p>${esc(q.data.company?.address||q.company.address)}</p><h2>${esc(q.reference)} · Revision ${q.revision}</h2><p>${esc(q.description)}</p><p>${esc(q.data.customer?.name)} · ${esc(q.data.property?.address)}</p><p>Expires ${date(q.expires_at)}</p>${status(q.expired&&q.status==='issued'?'expired':q.status)}<div class="table-scroll" tabindex="0" role="region" aria-label="Scrollable records"><table><thead><tr><th>Description</th><th>Qty</th><th>Unit · ZAR</th><th>Amount</th></tr></thead><tbody>${q.data.items.map((i:Row)=>`<tr><td>${esc(i.description)}<small>${esc(i.kind)}</small></td><td>${i.quantity}</td><td>${money(i.unit_cents)}</td><td>${money(Math.round(i.quantity*i.unit_cents))}</td></tr>`).join('')}</tbody></table></div><dl class="quote-totals"><dt>Subtotal</dt><dd>${money(q.data.subtotal_cents)}</dd><dt>Discount</dt><dd>${money(q.data.discount_cents)}</dd><dt>VAT ${q.data.vat_bps/100}%${q.data.vat_registered?' · '+esc(q.data.vat_number):' · Not VAT registered'}</dt><dd>${money(q.data.vat_cents)}</dd><dt>Total</dt><dd><strong>${money(q.data.total_cents)}</strong></dd></dl><p class="preserve">${esc(q.data.notes)}</p>${q.status==='issued'&&!q.expired&&!q.closed?`<form id="approval-form" class="form-grid"><div class="form-error wide" role="alert" hidden></div>${field('Your full name','name','','text','required maxlength="160"')}${select('Your decision','decision',[['accepted','Accept quotation'],['rejected','Reject quotation']])}${area('Notes (optional)','note','','maxlength="2000"')}<label class="check wide"><input type="checkbox" name="confirmed" required>I am authorized to make this decision and confirm this action.</label><p class="quiet wide">This private link records your action and stated name. It is not a digital signature or independent identity verification. No payment is collected.</p><button class="primary">Record my decision</button></form>`:`<p class="decision-status">${q.decision_at?esc(q.status)+' by '+esc(q.decision_by)+' · '+date(q.decision_at):'This quotation is no longer open for a decision.'}</p>`}</section><p class="quiet">Keep this link private. No payment processing is enabled.</p></main>`;wireLogo();document.querySelector('#approval-form')?.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as HTMLFormElement;await saveInline(f,async()=>{const b=values(f);await api('/approval/'+encodeURIComponent(token),'POST',{name:b.name,decision:b.decision,note:b.note,confirmed:b.confirmed==='on'});await approval();});});}catch(e){root.innerHTML=`<main class="approval-page"><div class="form-error" role="alert">${esc(errorText(e))}</div><a href="/">Back to MzansiPlumb</a></main>`;}}
if(/^#(reset-password|verify-email)\//.test(location.hash))void recovery();else if(location.pathname.startsWith('/approve/'))void approval();else void api('/auth/me').then(async r=>{user=r.user;csrf=r.csrf;await boot();}).catch(()=>auth());

function applyPermissions(){const permissions:Record<string,string>={'new-job':'jobs.write','edit-job':'jobs.write','cancel-job':'jobs.write','schedule-job':'schedule.write','new-team':'schedule.write','new-customer':'customers.write','edit-customer':'customers.write','new-property':'customers.write','edit-property':'customers.write','new-member':'company.manage','edit-member':'company.manage','new-quote':'quotes.write','edit-quote':'quotes.write','issue-quote':'quotes.write','revise-quote':'quotes.write','upload':'cards.write','complete-job':'jobs.complete','advanced-job-cost':'costs.write','advanced-revenue':'revenue.write','advanced-reverse-revenue':'revenue.write','advanced-new-stock':'inventory.write','advanced-edit-stock':'inventory.write','advanced-move-stock':'inventory.write','advanced-new-maintenance':'maintenance.write','advanced-edit-maintenance':'maintenance.write','advanced-new-template':'templates.write','advanced-edit-template':'templates.write','advanced-new-followup':'tasks.write','advanced-edit-followup':'tasks.write','advanced-reconcile':'company.manage','advanced-notification-read':'tasks.write'};document.querySelectorAll<HTMLElement>('[data-action]').forEach(el=>{const p=permissions[el.dataset.action||''];if(p&&!permitted(p))el.hidden=true;});if(!permitted('cards.write'))document.querySelectorAll<HTMLInputElement>('#job-card input,#job-card textarea,#job-card button,#job-card select').forEach(el=>el.disabled=true);if(!permitted('company.manage'))document.querySelectorAll<HTMLInputElement>('#company-form input,#company-form button').forEach(el=>el.disabled=true);}

async function recovery(){const [kind,token]=location.hash.slice(1).split('/'),reset=kind==='reset-password',verify=kind==='verify-email';root.innerHTML=`<main class="approval-page">${logo()}<section class="panel padded"><h1>${reset?'Reset password':verify?'Verify email':'Password recovery'}</h1><form id="recovery-form" class="form-grid"><div class="form-error wide" role="alert" hidden></div>${reset?field('New password','password','','password','required minlength="12" maxlength="128" autocomplete="new-password"')+field('Confirm new password','confirmation','','password','required minlength="12" maxlength="128" autocomplete="new-password"'):verify?'<p class="wide">Confirm that you requested verification for your account.</p>':field('Account email address','email','','email','required autocomplete="email"')}<button class="primary" type="submit">${reset?'Update password':verify?'Verify email':'Request recovery link'}</button><p id="recovery-result" class="quiet wide" role="status"></p></form><a href="/app">Return to sign in</a></section></main>`;wireLogo();document.querySelector('#recovery-form')!.addEventListener('submit',async e=>{e.preventDefault();const f=e.target as HTMLFormElement;await saveInline(f,async()=>{const b=values(f);if(reset&&b.password!==b.confirmation)throw new Error('Passwords do not match');const r=await api('/auth/'+(reset?'reset-password':verify?'verify-email':'forgot-password'),'POST',reset?{token,password:b.password}:verify?{token}:{email:b.email});document.querySelector('#recovery-result')!.textContent=r.message+(r.email_configured===false?' Email delivery is not configured.':'');if(reset||verify){history.replaceState(null,'','/app');f.querySelector('button')!.hidden=true;} });});}
